#!/usr/bin/env python3
import os,sys,subprocess,time
from pathlib import Path
args=sys.argv[1:]
if len(args)>2 and args[0]=='-C':
    repo=Path(args[1])
    snapshot='for-each-ref' in args and any('%(upstream:track)' in a for a in args)
    if snapshot and repo.parent==Path('/private/tmp') and repo.name.startswith('gitcraft rc ü squash-') and (repo/'f1.txt').is_file() and (repo/'f2.txt').is_file():
        count=subprocess.run(['/usr/bin/git','-C',str(repo),'rev-list','--count','HEAD'],stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,text=True)
        if count.returncode==0 and count.stdout.strip()=='2':
            try:
                fd=os.open(repo/'.git/gitcraft-validation-delay',os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)
            except FileExistsError:
                pass
            else:
                os.close(fd)
                with open('/tmp/gitcraft-pr164-delayed-git/events.log','a') as log:
                    log.write(f'delaying post-squash refs snapshot for 11 seconds: {repo.name}\n')
                time.sleep(11)
os.execv('/usr/bin/git',['/usr/bin/git',*args])
